  GAME_INIT: GameView;
  GAME_UPDATE_AND_INFORM: GameClientMessage;
  GAME_INFORM_PERSONAL: GameClientMessage;
  GAME_ERROR: string;
  GAME_UPDATE: GameView;
  GAME_TARGET: GameClientMessage;
  GAME_CHOOSE_ABILITY: AbilityPickerView;
